CREATE POLICY "Teachers upload live block audio" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'tutoring-materials' AND (storage.foldername(name))[1] = 'audio' AND EXISTS (SELECT 1 FROM public.tutoring_lessons l WHERE l.id::text = (storage.foldername(name))[2] AND (l.teacher_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::app_role))));
CREATE POLICY "Live participants read block audio" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'tutoring-materials' AND (storage.foldername(name))[1] = 'audio' AND EXISTS (SELECT 1 FROM public.tutoring_lessons l WHERE l.id::text = (storage.foldername(name))[2] AND (l.teacher_id = auth.uid() OR (l.student_id = auth.uid() AND EXISTS (SELECT 1 FROM public.tutoring_lesson_blocks b WHERE b.lesson_id = l.id AND b.visible_to_student = true AND b.payload->>'audio_path' = name)) OR public.has_role(auth.uid(), 'admin'::app_role))));